'use strict';
window.POSTAL_ROUTE=[
 {name:'Eckerö',lon:19.54361,lat:60.22017},{name:'Marsund',lon:19.67,lat:60.23},
 {name:'Boda',lon:19.8,lat:60.19},{name:'Färjsundet',lon:20.01326,lat:60.23909},
 {name:'Kastelholm',lon:20.08056,lat:60.23306},{name:'Bomarsund',lon:20.242,lat:60.212},
 {name:'Vårdö',lon:20.36667,lat:60.23333},{name:'Kumlinge',lon:20.78333,lat:60.26667}
];
(()=>{
 const dialog=document.querySelector('#archive'),content=document.querySelector('#archiveContent');
 const photos=[[1942,'25 juli'],[1952,'11 juli'],[1962,'5 juni'],[1975,'9 maj'],[1982,'12 maj'],[1991,'6 maj'],[1999,'10 juni'],[2007,'4 juni'],[2015,'20 maj'],[2021,'6 juni']];
 let context={year:2026,lon:19.941,lat:60.103};
 function url(year,embed=true){const inCity=context.lon>19.86&&context.lon<20.12&&context.lat>59.98&&context.lat<60.15,cp=mariehamnGrid(inCity?context.lon:19.941,inCity?context.lat:60.103).map(Math.round).join(',');return `https://karta.mariehamn.ax/IMS/${embed?'sv/embed':''}?layers=${year===2021?'Flygfoto%202021':'Baskarta'}&lon=Flygfoto%20${year}&cp=${cp}&z=2${embed?'&ui=z!o!b':''}`}
 function photo(year){const date=photos.find(p=>p[0]===year)[1];return `<section class="photo"><h3>${year} <small>${date}</small></h3><iframe title="Mariehamns stads flygfoto ${year}" src="${url(year)}" loading="eager" allowfullscreen></iframe><a href="${url(year,false)}" target="_blank" rel="noopener noreferrer">Öppna ${year} i stadens karta ↗</a></section>`}
 function regionalScan(id,title,src,ratio,vh){return `<section class="regional-scan"><div class="scanheading"><h3>${title}</h3><label>Förstora <input id="${id}Zoom" type="range" min="100" max="800" step="25" value="100" aria-label="Förstora ${title}"><output id="${id}Percent">100 %</output></label></div><div class="scanviewport" tabindex="0" aria-label="${title}, rulla för att utforska"><img id="${id}Scan" src="${src}" alt="${title}" style="width:min(100%,${vh*ratio}dvh);margin-inline:auto"></div></section>`}
 function bindRegionalZoom(id,ratio,vh){document.querySelector('#'+id+'Zoom').oninput=e=>{document.querySelector('#'+id+'Scan').style.width=`min(${e.target.value}%,${vh*ratio*Number(e.target.value)/100}dvh)`;document.querySelector('#'+id+'Percent').value=e.target.value+' %'}}
 function render(tab){document.querySelectorAll('[data-archive]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.archive===tab||(tab==='compare1800'&&b.dataset.archive==='1800'))));
  if(tab==='1800'||tab==='compare1800'){
   const compare=tab==='compare1800',credit='<p class="archivecredit">Karta öfver Åland · cirka 1800 · Uppsala universitetsbibliotek, Kart- och bildsamlingarna · Alvin 82661 · <a href="https://creativecommons.org/publicdomain/mark/1.0/" target="_blank" rel="noopener noreferrer">Public Domain</a>. <a href="https://www.alvin-portal.org/alvin/imageViewer.jsf?dsId=ATTACHMENT-0001&amp;pid=alvin-record%3A82661" target="_blank" rel="noopener noreferrer">Original och kataloguppgifter hos Alvin ↗</a> · <a href="assets/aland-ca1800-alvin.jpg" target="_blank" rel="noopener noreferrer">Öppna bildfilen ↗</a></p>';
   content.innerHTML=`<p class="archiveintro"><strong>Karta öfver Åland · cirka 1800.</strong> Följ vägarna mellan byar och kyrkor. Bilden täcker främst fasta Åland och delar av skärgården. Alvins datering är ungefärlig.</p><div class="fortress-controls"><button id="compareEarlyMaps">${compare?'Visa bara kartan från cirka 1800':'Jämför med 1894'}</button><button id="earlyMapYear">Gå till cirka 1800 i tidsresan</button></div><p class="archiveintro">Leta efter Jomala, Finström och Kastelholm. Hur skrivs namnen? ${compare?'Förstora och flytta varje karta för sig. Kartorna har olika täckning och skala.':'Förstora bilden och rulla för att läsa små detaljer.'} Originalet är inte geografiskt inpassat i huvudkartan.</p><div class="${compare?'early-map-comparison':'early-map-single'}">${regionalScan('early','Åland · cirka 1800','assets/aland-ca1800-alvin.jpg',4054/5000,compare?42:50)}${compare?regionalScan('later','Åland · 1894','assets/aland-1894.jpg',3381/2297,42):''}</div>${credit}${compare?'<p class="archivecredit">Kartan från 1894: British Library / Wikimedia Commons · Public Domain. <a href="https://commons.wikimedia.org/wiki/File:(1894)_MAP_OF_THE_%C3%85LAND_ISLANDS.jpg" target="_blank" rel="noopener noreferrer">Källuppgifter för 1894 års karta ↗</a></p>':''}`;
   bindRegionalZoom('early',4054/5000,compare?42:50);if(compare)bindRegionalZoom('later',3381/2297,42);
   document.querySelector('#compareEarlyMaps').onclick=()=>render(compare?'1800':'compare1800');
   document.querySelector('#earlyMapYear').onclick=()=>{dialog.close();window.openEarlyMapYear()};
   return;
  }
  if(tab==='pdc'){content.innerHTML=`<p class="archiveintro">Ålands historiska karta har kartlager från 1863, 1865/1872, 1893/1897 och 1916/1917. Där kan du jämföra äldre kartor med landskapet. Dessa lager öppnas hos originaltjänsten.</p><p><a href="https://historia.pdc.ax/" target="_blank" rel="noopener noreferrer">Utforska Ålands historiska karta ↗</a></p><p class="archivecredit">Vi har inte kopierat dessa kartlager: underlag för återanvändning och exakt inpassning har inte kunnat verifieras. Vår egen tidslinje använder daterade strandlinjer från samma modellkälla, maannousu.info.</p>`;return}
  if(tab==='compare'){content.innerHTML=`<p class="archiveintro">Samma startområde, två ögonblick i tiden. Flytta och zooma i varje bild för sig. Utanför 1942-bildens täckning syns stadens nutida baskarta. Leta efter hus, gator och förändrade stränder.</p><div class="photocompare">${photo(1942)}${photo(2021)}</div><p class="archivecredit">© Mariehamns stad · officiella kartvyer. Om bilderna inte visas, använd länkarna till stadens karta.</p>`;return}
  if(tab==='photo'){const nearest=photos.reduce((best,p)=>Math.abs(p[0]-context.year)<Math.abs(best-context.year)?p[0]:best,photos[0][0]);content.innerHTML=`<div class="photochooser"><label for="photoYear">Välj flygfoto</label><select id="photoYear">${photos.map(([y])=>`<option value="${y}" ${y===nearest?'selected':''}>${y}</option>`).join('')}</select><span>Valt år: ${context.year}. Närmaste flygfoto väljs automatiskt.</span></div><div id="singlePhoto">${photo(nearest)}</div><p class="archivecredit">© Mariehamns stad · officiell kartvy. Flygfotot visar fotograferingsdagen, inte nödvändigtvis tidslinjens år. Inom Mariehamn följer startvyn kartans centrum; annars visas centrala Mariehamn. Utanför fotots täckning kan nutida baskarta synas.</p>`;document.querySelector('#photoYear').onchange=e=>document.querySelector('#singlePhoto').innerHTML=photo(Number(e.target.value));return}
  if(tab==='1920'){
   const map=HistoricalOverlay.museum;
   content.innerHTML=`<div class="scanheading"><h3>Mariehamn · 1920-talet</h3><label>Förstora <input id="scanZoom" type="range" min="100" max="400" step="25" value="100" aria-label="Förstora historisk karta"><output id="scanPercent">100 %</output></label></div><p class="archiveintro"><strong>Museets bild av 1920-talets stad.</strong> Kartan visar modellstadens elva vitriner. Den återger en hel period, inte ett exakt läge år 1920. Röda ramar är museets indelning. Husbeskrivningarna bygger på arkivstudier och intervjuer.</p><div class="fortress-controls"><button id="museumOnMap">Visa museikartan på kartan</button><button id="museumCompareToday">Jämför med dagens vägar och hus</button><button id="museumComparePlan">Jämför med planen 1860</button></div><p class="archiveintro">Följ ett kvarter från gatan till gården. Kan ni hitta de små uthusen? Välj samma nummer nedan för att läsa om husen hos Nybyggarne.</p><nav class="vitrine-links" aria-label="Husbeskrivningar hos Nybyggarne">${Array.from({length:11},(_,i)=>`<a href="https://mpf.spfpension.fi/verksamhet/nybyggarne/vitriner/vitrin${i+1}/" target="_blank" rel="noopener noreferrer" aria-label="Vitrin ${i+1}: husbeskrivningar hos Nybyggarne (ny flik)">${i+1} ↗</a>`).join('')}</nav><div class="scanviewport" tabindex="0" aria-label="Mariehamn på 1920-talet, rulla för att utforska"><img id="archiveScan" src="${map.src}" alt="Mariehamn på 1920-talet: hus, gator, gårdar och stränder, med röda ramar och nummer för museets elva vitriner."></div><p id="museumImageStatus" class="archivecredit" role="status"></p><p class="archivecredit">Mariehamns Pensionärsförening / Nybyggarne · bilden hämtas från originalwebbplatsen. <a href="${map.source}" target="_blank" rel="noopener noreferrer">Om kartan och modellstaden ↗</a> · <a href="${map.src}" target="_blank" rel="noopener noreferrer">Öppna originalbilden ↗</a></p>`;
   const scan=document.querySelector('#archiveScan'),imageStatus=document.querySelector('#museumImageStatus');scan.onerror=()=>{imageStatus.textContent='Bilden kunde inte laddas. Använd länken till originalwebbplatsen nedan.'};
   document.querySelector('#scanZoom').oninput=e=>{scan.style.width=e.target.value+'%';document.querySelector('#scanPercent').value=e.target.value+' %'};
   document.querySelector('#museumOnMap').onclick=()=>{dialog.close();window.openCityMap('1920',1920)};
   document.querySelector('#museumCompareToday').onclick=()=>{dialog.close();window.openCityMap('1920',2026)};
   document.querySelector('#museumComparePlan').onclick=()=>{dialog.close();window.openCityMap('1860',1860)};
   return;
  }
  if(tab==='1860'){
   content.innerHTML=`<div class="scanheading"><h3>Mariehamn · stadsplan 1860</h3><label>Förstora <input id="scanZoom" type="range" min="100" max="400" step="25" value="100" aria-label="Förstora historisk karta"><output id="scanPercent">100 %</output></label></div><p class="archiveintro"><strong>En plan för staden som skulle byggas.</strong> G. Th. Chiewitz ritade planen 1859. Mariehamn grundades 1861. Byggnaderna på ritningen är planerade; bilden visar inte vilka hus som stod färdiga 1860.</p><div class="fortress-controls"><button id="planOnMap">Visa planen på kartan · 1860</button><button id="planCompareToday">Jämför med dagens vägar och hus</button></div><p class="archiveintro">Leta efter kyrkan i esplanadernas korsning, skolan strax söder om den, lasarettet i nordväst och hamnarna på båda sidor. Vilka delar känner ni igen idag? Förstora och rulla i bilden för att läsa texten.</p><div class="scanviewport" tabindex="0" aria-label="Mariehamns stadsplan, rulla för att utforska"><img id="archiveScan" src="assets/mariehamn-plan-1860.png" alt="Plan till reglering af staden Mariehamn på Åland: planerade kvarter, esplanader, kyrka, skola, lasarett och hamnar."></div><p class="archivecredit">G. Th. Chiewitz · ritning daterad november 1859, stadsplan 1860. Bildkopia tillhandahållen av användaren. <a href="https://www.mariehamn.ax/sites/default/files/attachments/guidedocument/generalplan_del2_03_plan.pdf" target="_blank" rel="noreferrer">Stadens beskrivning av den första stadsplanen ↗</a> · <a href="assets/mariehamn-plan-1860.png" target="_blank" rel="noreferrer">Öppna originalbilden ↗</a></p>`;
   document.querySelector('#scanZoom').oninput=e=>{document.querySelector('#archiveScan').style.width=e.target.value+'%';document.querySelector('#scanPercent').value=e.target.value+' %'};
   document.querySelector('#planOnMap').onclick=()=>{dialog.close();window.openCityPlan(1860)};
   document.querySelector('#planCompareToday').onclick=()=>{dialog.close();window.openCityPlan(2026)};
   return;
  }
  const postal=tab==='postal';
  const src=postal?'assets/postvag-1700.webp':'assets/aland-1894.jpg',title=postal?'Postvägen över Åland · 1700-talet':'Karta över Åland · 1894';
  content.innerHTML=`<div class="scanheading"><h3>${title}</h3><label>Förstora <input id="scanZoom" type="range" min="100" max="400" step="25" value="100" aria-label="Förstora historisk karta"><output id="scanPercent">100 %</output></label></div><p class="archiveintro">${postal?'Följ postförarnas väg på C. J. Carlssons karta. På vår tidskarta visas en förenklad del av förbindelsen mellan Eckerö och Kumlinge. Originalet visar en längre sträcka och fler hållpunkter.':'Leta efter välbekanta namn och jämför hur öarna avbildades 1894.'} Förstora bilden och rulla åt sidorna för att läsa detaljer. ${postal?'Originalet är inte inpassat i vår moderna karta.':'En ungefärligt inpassad version finns också under Kartunderlag i huvudkartan.'}</p><div class="scanviewport" tabindex="0" aria-label="Historisk karta, rulla för att utforska"><img id="archiveScan" src="${src}" alt="${title}"></div><p class="archivecredit">${postal?'C. J. Carlsson / Postmuseum, POST.044851 · DigitaltMuseum · Public Domain / CC0. Katalogen anger 1700-talet, med osäkerhet om närmare datering. <a href="https://digitaltmuseum.se/011024626117/karta" target="_blank" rel="noreferrer">Se originalets uppgifter ↗</a>':'British Library / Wikimedia Commons · Finland in the Nineteenth Century (1894) · Public Domain. <a href="https://commons.wikimedia.org/wiki/File:(1894)_MAP_OF_THE_%C3%85LAND_ISLANDS.jpg" target="_blank" rel="noreferrer">Se originalets uppgifter ↗</a>'}</p>`;
  document.querySelector('#scanZoom').oninput=e=>{document.querySelector('#archiveScan').style.width=e.target.value+'%';document.querySelector('#scanPercent').value=e.target.value+' %'};
 }
 document.querySelector('#openArchive').onclick=()=>{if(typeof pause==='function')pause();context=window.currentMapContext?.()||context;render('photo');dialog.showModal()};
 window.openEarlyMapArchive=(compare=false)=>{if(typeof pause==='function')pause();render(compare?'compare1800':'1800');dialog.showModal()};
 window.openCityMapArchive=mode=>{if(typeof pause==='function')pause();render(mode==='1920'?'1920':'1860');dialog.showModal()};
 window.openCityPlanArchive=()=>window.openCityMapArchive('1860');
 document.querySelector('#closeArchive').onclick=()=>dialog.close();
 document.querySelectorAll('[data-archive]').forEach(b=>b.onclick=()=>render(b.dataset.archive));
})();
